 * It is designed to handle various YAML structures including nested objects, arrays,
 * and scalar values. The input YAML content is considered fully trusted, so no
 * additional security restrictions are applied during parsing.
 * </p>
 */
public class YamlService {

    /**
     * Parses a YAML string and returns the corresponding Java object.
     * <p>
     * The method accepts a YAML string, parses it using SnakeYAML, and returns the
     * resulting object. If the input is null, empty, or contains invalid YAML syntax,
     * appropriate exceptions are thrown.
     * </p>
     *
     * @param yamlContent the YAML string to parse (must not be null or empty)
     * @return the parsed Java object (can be a Map, List, String, Number, Boolean, etc.)
     * @throws IllegalArgumentException if the input is null or empty
     * @throws YAMLException            if the YAML content is syntactically invalid
     */
    public Object parseUserYaml(String yamlContent) {
        // Validate input
        if (yamlContent == null || yamlContent.trim().isEmpty()) {
            throw new IllegalArgumentException("YAML content must not be null or empty");
        }

        // Create a SnakeYAML parser instance
        // Since the input is fully trusted, we use the default constructor which
        // supports all standard YAML types and Java object serialization.
        Yaml yaml = new Yaml();

        try {
            // Parse the YAML string into a Java object
            return yaml.load(yamlContent);
        } catch (YAMLException e) {
            // Re-throw with a more descriptive message
            throw new YAMLException("Failed to parse YAML content: " + e.getMessage(), e);
        } catch (Exception e) {
            // Catch any other unexpected exceptions (e.g., StackOverflowError from deep recursion)
            throw new RuntimeException("Unexpected error during YAML parsing", e);
        }
    }
}
